54	export function appendSystemPromptSection(systemPrompt: string, promptSection: string): string {
55	  const section = promptSection.trim();
56	  if (!section || systemPrompt.includes(section)) return systemPrompt;
57	
58	  const lines = systemPrompt.split("\n");
59	  const firstLineIndex = lines.findIndex((line) => line.includes(FIRST_LINE_MARKER));
60	  if (firstLineIndex !== -1) {
61	    return [
62	      ...lines.slice(0, firstLineIndex + 1),
63	      "",
64	      section,
65	      "",
66	      ...lines.slice(firstLineIndex + 1),
67	    ].join("\n");
68	  }
69	
70	  const toolsIndex = systemPrompt.indexOf(TOOLS_MARKER);
71	  if (toolsIndex !== -1) {
72	    return `${systemPrompt.slice(0, toolsIndex).trimEnd()}\n\n${section}\n${systemPrompt.slice(toolsIndex)}`;
73	  }
74	
75	  return `${systemPrompt.trimEnd()}\n\n${section}`;
76	}
