78	export default function systemPromptAppenderExtension(pi: ExtensionAPI) {
79	  pi.on("before_agent_start", async (event, ctx) => {
80	    const config = readConfig();
81	    if (!config.enabled) return undefined;
82	
83	    const promptSection = readPromptFile(config.promptPath);
84	    if (!promptSection) {
85	      if (ctx.hasUI) {
86	        ctx.ui.notify(`System prompt appender file not found or empty: ${config.promptPath}`, "warning");
87	      }
88	      return undefined;
89	    }
90	
91	    const systemPrompt = appendSystemPromptSection(event.systemPrompt, promptSection);
92	    if (systemPrompt === event.systemPrompt) return undefined;
93	
94	    return { systemPrompt };
95	  });
96	}
